INSERT INTO `menu` (`Id`, `Name`, `Description`, `Price`, `Picture`, `restaurantId`) VALUES
(1, 'Sajtburger McMoment® menü', 'Marhahúspogácsa zsemlében, ömlesztett cheddar sajtszelettel, savanyú uborkával, hagymával, ketchuppal és mustárral. Allergének: (glutén, tej, mustár, szezámmag)\r\nMenühöz tartozik: Sajtburger, kis burgonya, Coca-Cola® 0,4 l\r\n', 1430, '', 1),
(2, 'Big Mac® McMenü®', 'Hamburger marhahúspogácsa (2db), ömlesztett cheddar sajt szelet, hagyma darabok, jégsaláta, kapros savanyú uborka, Big Mac® szósz, szezámmagos zsemlében. Allergének: (glutén, tojás, tej, mustár, szezámmag)\r\nMenühöz tartozik: Big Mac®, közepes burgonya, Coca-Cola® 0,4 l\r\n', 2600, '', 1),
(3, 'McChicken McMenü®', 'Csirkemellfilé darabokból formázva, pácolva és panírozva, szezámmagos zsemlében, jégsalátával és McChicken® szósszal. Allergének: (glutén, tojás, tej, mustár, szezámmag)\r\nMenühöz tartozik: McChicken, közepes burgonya, Coca-Cola® 0,4 l\r\n', 2560, '', 1),
(4, 'WHOPPER® Baconnel és Sajttal Menü', 'WHOPPER® Baconnel és Sajttal \r\nAllergének: (glutén, mustár, tej, tojás, zeller, szezámmag, kén-dioxid)\r\nMenühöz tartozik: WHOPPER® Baconnel és Sajttal, közepes burgonya, Coca-Cola® 330 ml\r\n', 3150, '', 2),
(5, 'Bacon King Menü', 'Bacon King \r\nAllergének: (glutén, mustár, tej, tojás, szezámmag, kén-dioxid)\r\nMenühöz tartozik: Bacon King, közepes burgonya, Coca-Cola® 220 ml\r\n', 4700, '', 2),
(6, 'Solo kosár Menü', 'Ha egyedül kajálnál, ezt a kosarat neked találtuk ki. 8 db King Nuggets, 8 db hagymakarika, 1 db közepes burgonya és 2 db választható tálkás szósz, hogy tuti jóllakj. \r\nAllergének: (glutén, szója, tej)\r\nMenühöz tartozik: 8 db King Nuggets, 8 db hagymakarika, 1 db közepes burgonya és 2 db választható tálkás szósz\r\n', 2290, '', 2),
(7, 'Zinger Menü ', 'Zinger, sült burgonya és káposztasaláta vagy 2 Hot Wings csípős csirkeszárny\r\nMenühöz tartozik: Zinger, sült burgonya és káposztasaláta vagy 2 Hot Wings csípős csirkeszárny \r\n', 3090, '', 3),
(8, 'Kentucky Gold Grander', 'Kentucky Gold Grander, sült burgonya és káposztasaláta vagy 2 Hot Wings csípős csirkeszárny\r\nMenühöz tartozik: Kentucky Gold Grander, sült burgonya és káposztasaláta vagy 2 Hot Wings csípős csirkeszárny\r\n', 3990, '', 3),
(9, 'Twister Cassic', 'Twister, sült burgonya és káposztasaláta vagy Hot Wings csípős csirkeszárny\r\nMenühöz tartozik: Twister, sült burgonya és káposztasaláta vagy Hot Wings csípős csirkeszárny\r\n', 2890, '', 3),
(10, 'Big Daddy Steak Burger menü', '20dkg szaftos marhahús, olvasztott sajt, bacon, ropogós hagymakarika, csemegeuborka, saláta, lila hagyma, BBQ szósz, nagy adag sült burgonya\r\nMenühöz tartozik: Big Daddy Steak Burger, nagy adag sült burgonya\r\n', 3900, '', 5),
(11, 'Big Chopper Steak Burger menü', '20dkg szaftos marhahús, olvasztott sajt, tükörtojás, csemegeuborka, jégsaláta, ranch öntet, nagy adag sült burgonya\r\nMenühöz tartozik: Big Chopper Steak Burger, nagy adag sült burgonya\r\n', 3800, '', 5),
(12, 'Double Royal Basket', 'pirított zsemle, különlegesen grillezett 100% marhahús, paradicsom, lila hagyma, csemegeuborka, sajt, bacon, sült burgonya\r\nMenühöz tartozik: Double Royal Basket Burger, sült burgonya\r\n', 3200, '', 5),
(13, 'DönerTál Dupla Hússal', 'Frissen sült borjú vagy csirkehús, friss zöldségekkel ( káposzta, hagyma, uborka, paradicsom ) öntettel és körettel.\r\nMenühöz tartozik: DönerTál Dupla Hússal\r\n', 4490, '', 6),
